# Bám sách: trang 106–107 + đáp án + Mini dictionary unit 51. Không chép nguyên văn.
theory = (
 H("A", "How journalists get the news", "Nhà báo lấy tin như thế nào")
 + P("A text explains the different ways in which journalists find their stories.", "Một đoạn văn giải thích những cách nhà báo tìm ra tin bài.")
 + T([
    ("<b>put out</b>", "Companies and organisations make press releases available to everyone.", "Các công ty, tổ chức phát hành thông cáo báo chí."),
    ("<b>pick up</b>", "Journalists learn about stories by chance from their contacts (card in Unit 24).", "Nhà báo tình cờ biết được tin từ các mối quen (thẻ ở bài 24)."),
    ("<b>get out</b> / <b>confide in</b>", "A secret becomes known when a politician or film star tells something private to someone who can’t keep quiet.", "Một bí mật bị lộ khi chính trị gia hay ngôi sao điện ảnh kể chuyện riêng cho người không kín miệng."),
    ("<b>sound out</b>", "Journalists ask well-informed people for their opinion to check a rumour (card in Unit 45).", "Nhà báo hỏi ý những người nắm tin để kiểm chứng tin đồn (thẻ ở bài 45)."),
    ("<b>root out</b> / <b>ferret out</b>", "They search for information that is hard to find.", "Họ lùng sục những thông tin khó tìm."),
    ("<b>worm</b> sth <b>out of</b> sb", "They become skilled at getting stories from people who don’t want to talk.", "Họ rất giỏi moi chuyện từ những người không muốn nói."),
    ("<b>stake out</b>", "They may watch a person’s house continuously until they get the story.", "Họ có thể canh liên tục nhà một người cho đến khi có tin."),
    ("<b>write up</b>", "Finding a story may matter as much as writing it in its final form (demo card, Unit 15).", "Tìm ra tin có thể quan trọng ngang viết hoàn chỉnh bài báo (thẻ demo, bài 15)."),
 ])
 + H("B", "Political news", "Tin chính trị")
 + P("Two news reports: a protest about pensions, and an MP who joins an important committee.", "Hai bản tin: một cuộc biểu tình về lương hưu, và một nghị sĩ được vào một ủy ban quan trọng.")
 + T([
    ("<b>leak out</b>", "News of the government’s plan to raise the retirement age again became known.", "Tin về kế hoạch tăng tiếp tuổi nghỉ hưu của chính phủ bị lộ ra."),
    ("<b>walk out</b> / <b>join in</b>", "Workers of all ages left factories and offices to take part in public demonstrations.", "Người lao động mọi lứa tuổi bỏ nhà máy, công sở để tham gia biểu tình."),
    ("<b>head off</b> / <b>pass off</b>", "Police failed to stop the main march, but all the demonstrations happened without serious trouble.", "Cảnh sát không ngăn được cuộc tuần hành chính, nhưng mọi cuộc biểu tình đều diễn ra mà không có sự cố lớn."),
    ("<b>put down</b>", "The government denies it will use force to stop future protests.", "Chính phủ phủ nhận việc sẽ dùng vũ lực dập các cuộc biểu tình sau này."),
    ("<b>get in</b> / <b>get onto</b>", "Tim Brookes has been an MP since his party was first elected in 1997; he always wanted to be elected to the Environmental Committee.", "Tim Brookes làm nghị sĩ từ khi đảng của ông lần đầu thắng cử năm 1997; ông luôn muốn được bầu vào Ủy ban Môi trường."),
    ("<b>whip up</b>", "He managed to stir up a lot of support and won the place.", "Ông khuấy động được nhiều sự ủng hộ và giành được ghế."),
    ("<b>dumb down</b>", "Critics say he makes complex issues too simple; he says anything that gets people talking about the environment is worthwhile.", "Người chỉ trích nói ông đơn giản hóa quá mức các vấn đề phức tạp; ông cho rằng điều gì khiến người ta bàn về môi trường đều đáng làm."),
 ])
 + H("C", "The police and the army in the news", "Cảnh sát và quân đội trên báo")
 + T([
    ("<b>call up</b>", "If there aren’t enough volunteers, the government will order people to join the armed forces.", "Nếu không đủ người tình nguyện, chính phủ sẽ gọi người nhập ngũ."),
    ("<b>join up</b>", "The new general joined the army at 21.", "Vị tướng mới nhập ngũ năm 21 tuổi."),
    ("<b>hold out</b>", "The enemy continues to defend itself in the south (see the demo card, Unit 1).", "Quân địch tiếp tục cầm cự ở miền nam (xem thẻ demo, bài 1)."),
    ("<b>send in</b>", "The army will be sent to help earthquake victims.", "Quân đội sẽ được điều đến giúp nạn nhân động đất."),
    ("<b>pull out</b>", "Troops are expected to leave the area before May.", "Quân đội dự kiến rút khỏi khu vực trước tháng Năm."),
    ("<b>shoot down</b>", "Two planes were destroyed by enemy fire.", "Hai máy bay bị hỏa lực địch bắn rơi."),
    ("<b>give yourself up</b>", "The kidnapper let the police catch him.", "Kẻ bắt cóc ra đầu thú."),
    ("<b>move in</b>", "The police will go in to deal with the situation if it gets worse.", "Cảnh sát sẽ vào cuộc nếu tình hình leo thang."),
 ])
 + NOTE("<b>Over to you</b>: headlines often use phrasal verbs, possibly because they are brief and striking. Exercise 51.2 matches headlines such as <i>Oil protest passes off peacefully</i> and <i>Reservists called up as situation worsens</i> with extracts from the articles.",
        "<b>Over to you</b>: phrasal verb rất hay xuất hiện trong tít báo, có lẽ vì chúng ngắn và gây ấn tượng. Bài 51.2 ghép các tít như <i>Oil protest passes off peacefully</i> (biểu tình dầu mỏ diễn ra ôn hòa), <i>Reservists called up as situation worsens</i> (quân dự bị được gọi nhập ngũ khi tình hình xấu đi) với đoạn trích bài báo.")
)
